from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and separate each group of nested parentheses
    groups = []
    current_group = ""
    open_braces = 0

    for char in paren_string:
        if char == "(":
            open_braces += 1
        elif char == ")":
            open_braces -= 1

        current_group += char

        if open_braces == 0:
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each group is balanced and not nested within each other
    for group in groups:
        if group.count("(") != group.count(")"):
            raise ValueError("Unbalanced parentheses in group: {}".format(group))

    # Step 4: Return the list of separated groups
    return groups

